for (const row of corpus.recheckFences.cases) test(`controlled readonly recheck fence ${row.name}`, async () => {
 const root = independentRoot("f"), input = corpus.recheckFences, controller = new AbortController(), reason = Error("Original Source recheck canceled");
 const contract = JSON.parse(readFileSync(new URL("../🧬️schema/🔣️.json", import.meta.url), "utf8"));
 expect(new Ajv({ strict: true }).compile(contract.$defs.RecheckFenceCase)(row)).toBe(true);
 put(root, "package.json", { ...scope("neutral-fence", input.members), workspaces: input.current });
 for (const member of input.packages) put(root, member.path + "/package.json", { name: member.name, version: "1.0.0" });
 const before = readFileSync(join(root, "package.json")), oracle = glob.sync("members/**/package.json", { cwd: root, onlyFiles: true, followSymbolicLinks: false }).map(path => path.replace(/\/package.json$/u, "")).sort();
 let armed = false, changed = false, completed = 0;
 try {
  const operation = ownership.withCurrentBunWorkspaceOwnershipV1(root, { kind: "scope", owner: "." }, { signal: controller.signal, advance: async progress => {
   expect(progress.completedOperations).toBe(++completed);
   if (armed && !changed && progress.operation === (row.action === "late-manifest" ? "membership" : "frontier")) {
    changed = true;
    if (row.action === "cancel") controller.abort(reason);
    if (row.action === "manifest") put(root, "members/a/package.json", { name: "changed-source", version: "1.0.0" });
    if (row.action === "topology") put(root, "members/new/package.json", { name: "new-source", version: "1.0.0" });
    if (row.action === "symlink") { renameSync(join(root, "members/a"), join(root, "retired")); symlinkSync(join(root, "retired"), join(root, "members/a"), process.platform === "win32" ? "junction" : "dir"); }
    if (row.action === "late-manifest") put(root, "members/a/package.json", { name: "changed-late", version: "1.0.0" });
    if (row.action === "unrelated") put(root, "independent-notes.json", { text: "Concurrent authored document" });
   }
   await new Promise<void>(accept => setImmediate(accept));
  } }, async custody => {
   expect(custody.scopes[0]?.packages).toEqual(oracle);
   armed = true;
   await custody.recheck();
   return custody.scopes[0]?.packages;
  });
  if (row.outcome === "canceled") await expect(operation).rejects.toBe(reason);
  else if (row.outcome === "rejected") await expect(operation).rejects.toThrow();
  else expect(await operation).toEqual(oracle);
  expect(changed).toBe(true);
  expect(readFileSync(join(root, "package.json"))).toEqual(before);
 } finally { controller.abort(); rmSync(join(root, ".."), { recursive: true, force: true }); }
});
