const installations=new Set<Promise<unknown>>();
beforeEach(()=>{cancellation=new AbortController();});
afterEach(async()=>{cancellation.abort();await Promise.allSettled([...installations]);for(const path of fixtureContainers)rmSync(path,{recursive:true,force:true});fixtureContainers.clear();});
/** 📦️ Executes one native installation through its actual test-owned cancellation signal. */
const install=async(directory:string)=>{
 const signal=cancellation.signal,child=Bun.spawn([process.execPath,"install","--ignore-scripts"],{cwd:directory,stdout:"pipe",stderr:"pipe",signal});
 const job=Promise.all([child.exited,new Response(child.stderr).text(),new Response(child.stdout).text()]).then(([exitCode,stderr])=>({exitCode,stderr,canceled:signal.aborted}),error=>{if(!signal.aborted)throw error;return {exitCode:null,stderr:String(error),canceled:true};});
 installations.add(job);
 try{return await job;}finally{installations.delete(job);}
};
