 expect(node).toBeDefined();const decision=new Function(node!.getText(tree)+";return ownershipFrontierDecisionV1;")(),schema=JSON.parse(readFileSync(new URL("../🧬️schema/🔣️.json",import.meta.url),"utf8")),validate=new Ajv({strict:true}).compile(schema.$defs.FrontierReplayCase),db=new Database(":memory:");
 try{for(const row of corpus.frontierReplay){expect(validate(row),row.name).toBe(true);const oracle=db.query("select case when ?1 is null or ?2 is null then 'derive' when ?3=1 and ?1=?2 then 'reuse' else 'relist' end result").get(row.before,row.after,Number(row.settled))as{result:string};expect(oracle.result,row.name).toBe(row.expected);expect(decision(row.before,row.after,row.settled),row.name).toBe(oracle.result);}}finally{db.close();}
