test("actual ownership frontier avoids rediscovery and retains physical mutation refusals",async()=>{
 const native=createRequire(import.meta.url)("node:fs")as typeof import("node:fs"),cases=["none","source","output","missing-package","add","remove","rename","manifest","ancestor","cancel","final-yield","final-output"],roots=cases.map(()=>independentRoot("fr"));
 for(const root of roots){put(root,"package.json",{...scope("frontier",["members/**"]),workspaces:["members/a"]});put(root,"members/a/package.json",{name:"frontier-a",version:"1.0.0"});mkdirSync(join(root,"members/empty"));}
 const contract=JSON.parse(readFileSync(new URL("../🧬️schema/🔣️.json",import.meta.url),"utf8"));await new Promise(done=>setTimeout(done,contract.$defs.PhysicalLimits.const.listingSettleMilliseconds+50));
 for(const[index,kind]of cases.entries()){
  const root=roots[index]!,stop=new AbortController(),reason=Object.freeze({frontierOriginal:kind}),events:string[]=[],start=performance.now();let armed=false,last=0,seen=0,body=false;
  const mutate=()=>{if(kind==="final-yield")put(root,"members/late/package.json",{name:"late"});else if(kind==="final-output")mkdirSync(join(root,"members/a/node_modules"));else stop.abort(reason);};
  const operation=ownership.withPublishedBunWorkspaceOwnershipV1(root,{kind:"scope",owner:"."},{signal:stop.signal,advance:async row=>{events.push(row.operation);if(armed&&row.operation==="frontier"&&++seen===last){armed=false;mutate();}}},async custody=>{
   body=true;const from=events.length;
   if(kind==="source")writeFileSync(join(root,"members/a/value.ts"),"export const value=1;");
   if(kind==="output")mkdirSync(join(root,"members/a/node_modules"));
   if(kind==="missing-package")put(root,"members/empty/package.json",{name:"new-negative-decision"});
   if(kind==="add")put(root,"members/b/package.json",{name:"frontier-b"});
   if(kind==="remove")rmSync(join(root,"members/a"),{recursive:true});
   if(kind==="rename")renameSync(join(root,"members/a"),join(root,"members/b"));
   if(kind==="manifest"){const file=join(root,"members/a/package.json"),before=native.statSync(file);writeFileSync(file,readFileSync(file,"utf8").replace("frontier-a","frontier-z"));native.utimesSync(file,before.atime,before.mtime);}
   if(kind==="ancestor"){renameSync(join(root,"members"),join(root,"moved"));mkdirSync(join(root,"members"));put(root,"members/a/package.json",{name:"frontier-a",version:"1.0.0"});}
   if(["cancel","final-yield","final-output"].includes(kind)){last=custody.observed().paths.length;armed=true;}
   await custody.recheck();
   if(["none","source","output","final-output"].includes(kind)){const actual=events.slice(from);expect(actual.filter(value=>value==="state"||value==="list")).toEqual([]);expect(actual.filter(value=>value==="frontier").length).toBeGreaterThan(0);}
  });
  if(["none","source","output","final-output"].includes(kind))await operation;else{let rejected=false,error:unknown;try{await operation;}catch(failure){rejected=true;error=failure;}expect(rejected,kind).toBe(true);if(kind==="cancel")expect(error).toBe(reason);else expect(String(error),kind).toMatch(/changed|drift|real directory/u);}
  expect(body,kind).toBe(true);
  const oracle=glob.sync("members/**/package.json",{cwd:root,followSymbolicLinks:false}).map(path=>path.slice(0,-13)).sort();if(kind==="none")expect(oracle).toEqual(["members/a"]);
  console.log("[DEBUG] ownership frontier "+JSON.stringify({kind,elapsedMs:Math.round(performance.now()-start),discoveryStates:events.filter(value=>value==="state").length,replayedStates:events.filter(value=>value==="frontier").length}));
 }
});

